import{z as A,x as d,o as E,c as B,q as i,j as n,D as e,d as t,s as o,S as l,b as r}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"点击劫持","description":"","frontmatter":{"title":"点击劫持","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/clickjacking.md","filePath":"cs/clickjacking.md","lastUpdated":1791063341000}'),c={name:"cs/clickjacking.md"};function p(m,a,C,D,f,S){const s=d("Mermaid");return E(),B("div",null,[a[2]||(a[2]=i('<h1 id="点击劫持" tabindex="-1">点击劫持 <a class="header-anchor" href="#点击劫持" aria-label="Permalink to &quot;点击劫持&quot;">​</a></h1><div class="epigraph"><p>把目标页嵌进透明框，用户以为在点上层 UI，实际点在下层敏感动作上。防御是不让自己被嵌，或要求额外确认，而不是靠用户看仔细。</p><footer>—— 据 OWASP Clickjacking；RFC 7034 X-Frame-Options；CSP frame-ancestors</footer></div><p>上一课<a href="/cs/cors">CORS</a>管的是跨源读；缺口是<strong>用户的点击被套层</strong>——这类攻击根本不需要读响应。本课讲嵌框机制与防御头，不给钓鱼页制作步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>iframe 把敏感页嵌进攻击者页面，再用透明度与 z-index 让它藏在诱饵 UI 下面：用户以为点的是「领奖品」，实际点的是下层页面里的「转账确认」。<span class="marginnote">术语翻译：iframe 是网页里的「画中画」——在一个页面里再嵌一个能独立加载别处页面的窗口。攻击的空门在于它有透明度和图层：把敏感页调成几乎透明、垫在漂亮的诱饵按钮下面，你眼睛看到的是上层，鼠标点到的却是下层。</span>防御是拒绝被嵌：X-Frame-Options 的 DENY/SAMEORIGIN，或更强的 CSP frame-ancestors。缺口是两处：老浏览器不认 frame-ancestors 时要双头并发；以及确实需要被第三方嵌入（支付、挂件）时怎么写精细的白名单策略。</p><h3 id="ui-完整性" tabindex="-1">UI 完整性 <a class="header-anchor" href="#ui-完整性" aria-label="Permalink to &quot;UI 完整性&quot;">​</a></h3><p>本质是 UI 完整性：用户意图与发出的请求错位。与 CSRF 是亲戚但不同层——CSRF 伪造请求来源，点击劫持伪造点击目标，是它的视觉版本。</p><p><span class="marginnote">OWASP。本课禁止制作点击劫持页面。SameSite 不单独解决嵌框点击。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法两层：响应头拒绝被任意嵌（frame-ancestors 优先，X-Frame-Options 兜底）；敏感动作再加应用内二次确认——重输密码或专用确认控件，即便页面被套，动作也不会随一次点击完成。下一课 SSRF：服务器被拐去请求内网。</p>',11)),(E(),n(l,null,{default:e(()=>[o(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOP%5B%22%E5%8F%AF%E8%A7%81%20UI%22%5D%20--%3E%20CLICK%5B%22%E7%94%A8%E6%88%B7%E7%82%B9%E5%87%BB%22%5D%0A%20%20HIDDEN%5B%22%E9%80%8F%E6%98%8E%E5%B5%8C%E6%A1%86%22%5D%20--%3E%20CLICK%0A%20%20CLICK%20--%3E%20ACT%5B%22%E6%95%8F%E6%84%9F%E5%8A%A8%E4%BD%9C%E5%9C%A8%E8%A2%AB%E5%B5%8C%E6%BA%90%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"机制视角：浏览器是用户的代理人，但代理人「所见」可被视觉混淆——用户对自己点了什么有完全判断力，只是判断依据的画面被调了包。防御哲学因此是服务器侧不得假设 UI 完整：敏感操作要么拒绝被嵌，要么要求嵌不掉的额外证据（重认证），而不是指望用户看仔细。SSRF 下一课把代理人换成服务器自己。",-1)),a[5]||(a[5]=r("p",null,"服务器侧的几道防线如何分工：",-1)),(E(),n(l,null,{default:e(()=>[o(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20EMB%5B%22%E7%AC%AC%E4%B8%89%E6%96%B9%E9%A1%B5%E9%9D%A2%E8%AF%95%E5%9B%BE%E5%B5%8C%E6%A1%86%22%5D%20--%3E%20FA%5B%22CSP%20frame-ancestors%20%E7%99%BD%E5%90%8D%E5%8D%95%22%5D%0A%20%20FA%20--%20%22%E4%B8%8D%E5%9C%A8%E7%99%BD%E5%90%8D%E5%8D%95%22%20--%3E%20BLK%5B%22%E6%B5%8F%E8%A7%88%E5%99%A8%E6%8B%92%E7%BB%9D%E6%B8%B2%E6%9F%93%E5%B5%8C%E6%A1%86%22%5D%0A%20%20FA%20--%20%22%E7%99%BD%E5%90%8D%E5%8D%95%E5%86%85%E6%88%96%E6%B5%8F%E8%A7%88%E5%99%A8%E4%B8%8D%E6%94%AF%E6%8C%81%22%20--%3E%20XFO%5B%22X-Frame-Options%20%E5%85%9C%E5%BA%95%22%5D%0A%20%20XFO%20--%20%22DENY%20%E6%88%96%20SAMEORIGIN%20%E4%B8%8D%E7%AC%A6%22%20--%3E%20BLK%0A%20%20XFO%20--%20%22%E5%85%81%E8%AE%B8%E5%B5%8C%E5%85%A5%22%20--%3E%20CONF%5B%22%E6%95%8F%E6%84%9F%E5%8A%A8%E4%BD%9C%E4%BB%8D%E9%9C%80%E4%BA%8C%E6%AC%A1%E7%A1%AE%E8%AE%A4%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>零制作教程；边界要点名：防御头只保护自己不被嵌，管不了自家页面作为顶层时被用户导入假站——那是钓鱼与 origin 校验的事。<span class="marginnote">为什么「双头并发」：frame-ancestors 是 CSP 的新指令，老浏览器可能整条不认，这时连拒绝被嵌的机会都没有；同时发 X-Frame-Options 等于给新旧两代浏览器各上一把锁。防御头不是二选一，是按能力逐级兜底。</span>SSRF 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CORS 挡读；点击劫持骗点击。</li><li>frame-ancestors 与 XFO 拒绝被嵌。</li><li>敏感动作二次确认。</li><li>下一课 SSRF。</li><li>出处：RFC 7034；CSP frame-ancestors；OWASP。</li></ul>',4))])}const u=A(c,[["render",p]]);export{h as __pageData,u as default};
